ALTER POLICY cq_select_folder ON public.meta_contato_qualificacao USING (EXISTS (SELECT 1 FROM meta_whatsapp_contatos c WHERE c.id = meta_contato_qualificacao.contato_id AND can_view_meta_contato_folder((select auth.uid()), c.folder_id)));
ALTER POLICY meta_mensagens_folder_member_select ON public.meta_whatsapp_mensagens USING (EXISTS (SELECT 1 FROM meta_whatsapp_contatos c WHERE c.instancia_id = meta_whatsapp_mensagens.instancia_id AND NOT (c.telefone IS DISTINCT FROM meta_whatsapp_mensagens.telefone) AND can_view_meta_contato_folder((select auth.uid()), c.folder_id)));
ALTER POLICY meta_msgs_folder_restrict ON public.meta_whatsapp_mensagens USING ((select has_role((select auth.uid()), 'admin'::app_role)) OR NOT (EXISTS (SELECT 1 FROM meta_whatsapp_contatos c WHERE c.instancia_id = meta_whatsapp_mensagens.instancia_id AND NOT (c.telefone IS DISTINCT FROM meta_whatsapp_mensagens.telefone) AND c.folder_id IS NOT NULL AND NOT can_access_meta_folder((select auth.uid()), c.folder_id))));